/* `node scripts/troubleshooting.mjs`: write the "Als een script misgaat" table in CONTRIBUTING.md from the failures
   recovery.mjs recognises, so the docs say exactly what the scripts say. scripts/docs.test.mjs fails when it is out of
   date. */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { ROOT } from './dev-config.mjs';
import { FAILURES } from './lib/recovery.mjs';

export const FILE = resolve(ROOT, 'CONTRIBUTING.md');
const START =
  '<!-- troubleshooting:start (generated by node scripts/troubleshooting.mjs from scripts/lib/recovery.mjs) -->';
const END = '<!-- troubleshooting:end -->';

/* Placeholders such as <package> would be read as HTML. */
const cell = (text) =>
  text.replace(/\|/g, '\\|').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\s+/g, ' ').trim();

/** The markdown table: one row per failure, in the order recovery.mjs tries them. */
export function renderTable(failures = FAILURES) {
  return [
    '| Herkend als | Waarom | Wat te doen |',
    '| ----------- | ------ | ----------- |',
    ...failures.map(({ kind, why, fix }) => `| \`${kind}\` | ${cell(why)} | ${cell(fix)} |`),
  ].join('\n');
}

/** `markdown` with the block between the markers replaced; throws when the markers are missing. */
export function withTable(markdown, table = renderTable()) {
  const start = markdown.indexOf(START);
  const end = markdown.indexOf(END);
  if (start === -1 || end < start) throw new Error(`CONTRIBUTING.md has no ${START} … ${END} block`);
  /* Prettier would align the columns (and lint-staged runs it): the generated table stays as generated. */
  const body = `<!-- prettier-ignore-start -->\n${table}\n<!-- prettier-ignore-end -->`;
  return `${markdown.slice(0, start + START.length)}\n\n${body}\n\n${markdown.slice(end)}`;
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(ROOT, 'scripts/troubleshooting.mjs')) {
  const before = readFileSync(FILE, 'utf8');
  const after = withTable(before);
  if (after === before) console.log('  CONTRIBUTING.md is up to date.');
  else {
    writeFileSync(FILE, after);
    console.log('  Updated the troubleshooting table in CONTRIBUTING.md.');
  }
}
